test(
  'should edit own comment on the discussion',
  async () => {
    await renderDiscussion();

    const comment = 'Hello World';
    const editedComment = 'Hello Edited World';

    await userEvent.click(
      screen.getByRole('button', { name: /create comment/i }),
    );

    const createDrawer = await screen.findByRole('dialog', {
      name: /create comment/i,
    });

    await userEvent.type(
      await within(createDrawer).findByText(/body/i),
      comment,
    );

    await userEvent.click(
      await within(createDrawer).findByRole('button', { name: /submit/i }),
    );

    await waitFor(() => expect(createDrawer).not.toBeInTheDocument());

    await screen.findByText(comment);

    const commentsList = await screen.findByRole('list', {
      name: 'comments',
    });

    const commentElement = (
      await within(commentsList).findAllByRole('listitem')
    )[0];

    await userEvent.click(
      within(commentElement).getByRole('button', { name: /edit comment/i }),
    );

    const editDrawer = await screen.findByRole('dialog', {
      name: /edit comment/i,
    });

    const bodyField = within(editDrawer).getByRole('textbox');
    expect(bodyField).toHaveValue(comment);

    await userEvent.clear(bodyField);
    await userEvent.type(bodyField, editedComment);

    await userEvent.click(
      within(editDrawer).getByRole('button', { name: /submit/i }),
    );

    await screen.findByText(/comment updated/i);

    await waitFor(() => expect(editDrawer).not.toBeInTheDocument());

    expect(await screen.findByText(editedComment)).toBeInTheDocument();
    expect(within(commentsList).queryByText(comment)).not.toBeInTheDocument();
  },
  {
    timeout: 20000,
  },
);
EOF
